50	/// Finds a name written in a file: the declaration it names and the file declaring it, through imports.
51	pub(crate) trait Lookup<'a>: Fn(&str, &Utf8Path) -> Option<(Declaration<'a>, Utf8PathBuf)> {}
52	
53	impl<'a, F: Fn(&str, &Utf8Path) -> Option<(Declaration<'a>, Utf8PathBuf)>> Lookup<'a> for F {}
54	
55	impl PropsType {
56	    /// The members a forwarding target's props type reaches outside the ambient declarations, as `forwarding` takes them:
57	    /// its own, its picked keys and those of the interfaces it extends or intersects, in name order. Read from the
58	    /// syntax, so the same in both lanes, and known before the target is resolved.
59	    pub(crate) fn reachable_members(&self) -> Vec<Member> {
60	        let names: BTreeSet<&String> = self.own.iter().chain(&self.picked).chain(&self.inherited).collect();
61	        names.into_iter().map(|name| Member { name: name.clone(), own: true, ..Member::default() }).collect()
62	    }
63	
64	    /// Reads the props type of `mapping`, finding each name it writes with `lookup` from the file that writes it (the
65	    /// component's, then the declaring file of each declaration it reaches). The members of a base it extends or
66	    /// intersects are inherited: the lanes report them, and only [`PropsType::reachable_members`] reads them.
67	    pub(crate) fn read<'a>(mapping: &ComponentMapping, lookup: impl Lookup<'a>) -> Self {
68	        let mut read = Self { defaulted: mapping.param_defaults.keys().cloned().collect(), ..Self::default() };
69	        let from = mapping.file_path.as_path();
70	        // `props: Pick<Base, Keys>` is the mapping's own name and arguments, not a declaration to look up.
71	        read.pick(&mapping.props_type_name, &mapping.props_type_args, from, &lookup);
72	        match lookup(&mapping.props_type_name, from) {
73	            Some((Declaration::Interface(interface), _)) => {
74	                read.interface = Some((interface.name.to_string(), interface.file_path.to_string()));
75	                read.own.extend(interface.props.iter().map(|prop| prop.name.clone()));
76	                read.bases(interface, &lookup, 0);
77	            }
78	            Some((Declaration::Alias(alias), declared)) => match alias {
79	                CollectedTypeAlias::Pick { keys, .. } => read.keys(keys, &declared, &lookup, 0),
80	                // A union's arms are each the props type (a discriminated union's fields are its own).
81	                CollectedTypeAlias::Intersection { members, .. } | CollectedTypeAlias::Union { members, .. } => {
82	                    members.iter().for_each(|member| read.part(member, &declared, &lookup));
83	                }
84	                CollectedTypeAlias::Passthrough { target: part, .. }
85	                | CollectedTypeAlias::Partial { base: part, .. }
86	                | CollectedTypeAlias::Required { base: part, .. } => read.part(part, &declared, &lookup),
87	                CollectedTypeAlias::Omit { .. } | CollectedTypeAlias::LiteralUnion { .. } => {}
88	            },
89	            None => {}
90	        }
91	        read
92	    }
93	
94	    /// The members `interface`'s bases declare outside the ambient declarations, through their own bases, each base
95	    /// found from the file that names it; and the keys a `Pick` among them names.
96	    fn bases<'a>(&mut self, interface: &CollectedInterface, lookup: &impl Lookup<'a>, depth: u8) {
97	        for base in &interface.extends {
98	            let (ExtendsRef::SameFile { name, type_args } | ExtendsRef::Imported { local_name: name, type_args, .. }) =
99	                base
100	            else {
101	                continue;
102	            };
103	            self.pick(name, type_args, &interface.file_path, lookup);
104	            self.inherit(name, &interface.file_path, lookup, depth);
105	        }
106	    }
107	
108	    /// The members the interface `name` written in `from` declares and inherits, unless it is ambient.
109	    fn inherit<'a>(&mut self, name: &str, from: &Utf8Path, lookup: &impl Lookup<'a>, depth: u8) {
110	        if depth >= MAX_ALIAS_DEPTH {
111	            return;
112	        }
113	        if let Some((Declaration::Interface(base), declared)) = lookup(name, from)
114	            && !crate::origin::declaration_origin(declared.as_str()).is_ambient()
115	        {
116	            self.inherited.extend(base.props.iter().map(|prop| prop.name.clone()));
117	            self.bases(base, lookup, depth + 1);
118	        }
119	    }
120	
121	    /// One part of the props type written in `from`: a type literal's fields are its own, an intersection's parts are
122	    /// parts, a `Pick` names its keys; any other name is a base.
123	    fn part<'a>(&mut self, part: &CollectedType, from: &Utf8Path, lookup: &impl Lookup<'a>) {
124	        match part {
125	            CollectedType::Object(fields) | CollectedType::Callable { fields, .. } => {
126	                self.own.extend(fields.iter().map(|field| field.name.clone()));
127	            }
128	            CollectedType::Intersection(parts) | CollectedType::Union(parts) => {
129	                parts.iter().for_each(|part| self.part(part, from, lookup));
130	            }
131	            CollectedType::Named { name, args } => {
132	                self.pick(name, args, from, lookup);
133	                self.inherit(name, from, lookup, 0);
134	            }
135	            _ => {}
136	        }
137	    }
138	
139	    /// The keys of `name<args>` written in `from` when it is `Pick<Base, Keys>`, or a `Pick` under a utility that keeps
140	    /// the keys it names (`Omit`, `Partial`, `Required`, `Readonly`: an omitted key no longer reaches the component, so
141	    /// naming it changes nothing), or a type alias whose body is one of these. Any other form names no key.
142	    fn pick<'a>(&mut self, name: &str, args: &[CollectedType], from: &Utf8Path, lookup: &impl Lookup<'a>) {
143	        self.picks(name, args, from, lookup, 0);
144	    }
145	
146	    fn picks<'a>(&mut self, name: &str, args: &[CollectedType], from: &Utf8Path, lookup: &impl Lookup<'a>, depth: u8) {
147	        if depth >= MAX_ALIAS_DEPTH {
148	            return;
149	        }
150	        match (name, args) {
151	            ("Pick", [_, keys]) => self.keys(keys, from, lookup, 0),
152	            ("Omit", [base, keys]) => {
153	                // The omitted keys are not picked; only whether they are a closed set of literals is kept.
154	                let mut omitted = Self::default();
155	                omitted.keys(keys, from, lookup, 0);
156	                self.declined |= omitted.declined;
157	                if let CollectedType::Named { name, args } = base {
158	                    self.picks(name, args, from, lookup, depth + 1);
159	                }
160	            }
161	            ("Partial" | "Required" | "Readonly", [CollectedType::Named { name, args }, ..]) => {
162	                self.picks(name, args, from, lookup, depth + 1);
163	            }
164	            (_, []) => {
165	                let Some((Declaration::Alias(alias), declared)) = lookup(name, from) else { return };
166	                let base = match alias {
167	                    CollectedTypeAlias::Pick { keys, .. } => {
168	                        self.keys(keys, &declared, lookup, 0);
169	                        return;
170	                    }
171	                    CollectedTypeAlias::Omit { base, keys, .. } => {
172	                        // As an `Omit` written in place: its keys decide only whether it is declined.
173	                        let mut omitted = Self::default();
174	                        omitted.keys(keys, &declared, lookup, 0);
175	                        self.declined |= omitted.declined;
176	                        base
177	                    }
178	                    CollectedTypeAlias::Partial { base, .. }
179	                    | CollectedTypeAlias::Required { base, .. }
180	                    | CollectedTypeAlias::Passthrough { target: base, .. } => base,
181	                    CollectedTypeAlias::LiteralUnion { .. }
182	                    | CollectedTypeAlias::Union { .. }
183	                    | CollectedTypeAlias::Intersection { .. } => return,
184	                };
185	                if let CollectedType::Named { name, args } = base {
186	                    self.picks(name, args, &declared, lookup, depth + 1);
187	                }
188	            }
189	            _ => {}
190	        }
191	    }
