193	    /// The string literal keys `keys` written in `from` names, through unions and aliases, each alias found from the
194	    /// file that names it.
195	    fn keys<'a>(&mut self, keys: &CollectedType, from: &Utf8Path, lookup: &impl Lookup<'a>, depth: u8) {
196	        match keys {
197	            CollectedType::StringLiteral(key) => {
198	                self.picked.insert(key.to_string());
199	            }
200	            CollectedType::Union(keys) => keys.iter().for_each(|key| self.keys(key, from, lookup, depth)),
201	            CollectedType::Named { name, args } if args.is_empty() && depth < MAX_ALIAS_DEPTH => {
202	                let Some((Declaration::Alias(alias), declared)) = lookup(name, from) else {
203	                    self.declined = true;
204	                    return;
205	                };
206	                match alias {
207	                    CollectedTypeAlias::LiteralUnion { members, .. } => self.picked.extend(members.iter().cloned()),
208	                    CollectedTypeAlias::Passthrough { target, .. } => self.keys(target, &declared, lookup, depth + 1),
209	                    CollectedTypeAlias::Union { members, .. } => {
210	                        members.iter().for_each(|key| self.keys(key, &declared, lookup, depth + 1));
211	                    }
212	                    CollectedTypeAlias::Pick { .. }
213	                    | CollectedTypeAlias::Omit { .. }
214	                    | CollectedTypeAlias::Intersection { .. }
215	                    | CollectedTypeAlias::Partial { .. }
216	                    | CollectedTypeAlias::Required { .. } => self.declined = true,
217	                }
218	            }
219	            // Any other key form (`string`, `string & {}`, a template literal, `keyof X`, an alias past the depth)
220	            // is not a closed set of literals.
221	            _ => self.declined = true,
222	        }
223	    }
